1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	const DEDUCTIBLE = 100;
12	const CAP_MULTIPLE = 2;
13	
14	const BASE_PREMIUMS = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	} as const;
22	
23	// What an item is insured FOR, as opposed to what insuring it costs. The cap on
24	// claims is derived from these, so premium discounts never move it.
25	const INSURANCE_VALUES = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	} as const;
33	
34	// The six priced types are the domain, so they are derived from the premium
35	// table rather than restated: a type nobody prices cannot be insured. The
36	// unknown-type case (broomstick) is still a runtime error the tests will drive.
37	type ItemType = keyof typeof BASE_PREMIUMS;
38	
39	// Components (as opposed to main items) are the only things the block rule
40	// applies to, so the distinction has to be data, not a price coincidence.
41	// Typed as a set of ItemType so a component can never name an unpriced type.
42	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
43	
44	const PERCENT_WHOLE = 100;
45	
46	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
47	// floating-point error that shifts the spec's round-up in MHPCO's favour.
48	const percentOf = (percent: number, amount: number): number =>
49	  (amount * percent) / PERCENT_WHOLE;
50	
51	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
52	// round up, payouts (MHPCO pays) round down.
53	const roundPremiumInMHPCOsFavour = Math.ceil;
54	
55	export type QuoteResult = { premium: number };
56	
57	export type ClaimResult = { payout: number; remainingCap: number };
58	
59	export type ScenarioResult = QuoteResult | ClaimResult;
60	
61	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
62	// the surcharge and claim tests still to come). They are typed as optional so
63	// the scenarios the tests actually send typecheck, without pricing them.
64	type Item = {
65	  type: ItemType;
66	  material?: string;
67	  enchantment?: number;
68	  cursed?: boolean;
69	};
70	
71	type Damage = { itemType: string; amount: number };
72	
73	type Incident = { cause: string; damages: Damage[] };
74	
75	type QuoteStep = { op: "quote"; items: Item[] };
76	
77	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
78	
79	type Step = QuoteStep | ClaimStep;
80	
81	type Customer = { yearsWithMHPCO: number };
82	
83	// `op` is still unread: the claim tests will reach for it.
84	type Scenario = {
85	  customer: Customer;
86	  steps: Step[];
87	};
88	
89	const sum = (amounts: number[]): number =>
90	  amounts.reduce((total, amount) => total + amount, 0);
91	
92	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
93	
94	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
95	
96	// Groups of items that are "alike" — same type. The type is kept alongside the
97	// items because the block rule asks about it; recovering it from items[0] would
98	// make every reader re-derive that a group is non-empty and homogeneous.
99	type AlikeItems = { type: ItemType; items: Item[] };
100	
101	const groupByType = (items: Item[]): AlikeItems[] => {
102	  const groups = new Map<ItemType, Item[]>();
103	  for (const item of items) {
104	    const group = groups.get(item.type) ?? [];
105	    group.push(item);
106	    groups.set(item.type, group);
107	  }
108	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
109	};
110	
111	// A block is a discount on the components' combined base premium, not a flat
112	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
113	// 20 % stays visible as the rule it is.
114	const blockBasePremium = (items: Item[]): number => {
115	  const undiscounted = sumBasePremiums(items);
116	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
117	};
118	
119	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
120	// pile is never cheaper than the block it contains. Components only — three
121	// swords are three separate insurances, not a discounted building block.
122	const formsABlock = ({ type, items }: AlikeItems): boolean =>
123	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
124	
125	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
126	  formsABlock(alikeItems)
127	    ? blockBasePremium(alikeItems.items)
128	    : sumBasePremiums(alikeItems.items);
129	
130	// Priced per group of alike items rather than over the whole list, so 3 runes
131	// and 3 moonstones each form their own block.
132	const policyBasePremiumFor = (items: Item[]): number =>
133	  sum(groupByType(items).map(basePremiumForGroup));
134	
135	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
136	  applies ? percentOf(percent, amount) : 0;
137	
138	// Each item-specific surcharge is a percentage of the affected item's OWN base
139	// premium, so every rule reads as "this much, when this holds". The terms are
140	// summed rather than chosen between: an item can trigger several at once.
141	//
142	// Deliberately two explicit terms rather than a table of rules. The shared
143	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
144	// a threshold over an optional number), and nothing in the remaining spec adds
145	// a third item-specific surcharge to generalise over.
146	const surchargeFor = (item: Item): number => {
147	  const base = basePremiumForItem(item);
148	  return (
149	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
150	    percentOfWhen(
151	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
152	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
153	      base,
154	    )
155	  );
156	};
157	
158	// Charged alongside the policy base premium — never folded into it, or the
159	// policy-wide modifiers would compound on top of them.
160	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
161	
162	// Unlike the item-specific surcharges, these are percentages of the WHOLE
163	// policy's base premium. Each is returned already signed — a surcharge is
164	// positive, a discount negative — so the rule and its direction stay on one
165	// line instead of the sign living in a `+`/`-` further down the sum.
166	const policyModifiersFor = (
167	  policyBasePremium: number,
168	  customer: Customer,
169	  isFollowUpContract: boolean,
170	): number[] => [
171	  // Applies to every quote, follow-ups included: the spec treats each item in a
172	  // quote as newly insured, regardless of how long the customer has been around.
173	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
174	  -percentOfWhen(
175	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
176	    LOYALTY_DISCOUNT_PERCENT,
177	    policyBasePremium,
178	  ),
179	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
180	];
181	
182	// The order of the terms is the order of the spec's rules: what the items are
183	// worth, what they individually cost extra, what the policy as a whole is
184	// adjusted by, and MHPCO's fee on top.
185	const quoteFor = (
186	  items: Item[],
187	  customer: Customer,
188	  isFollowUpContract: boolean,
189	): ScenarioResult => {
190	  const policyBasePremium = policyBasePremiumFor(items);
191	  const premium = roundPremiumInMHPCOsFavour(
192	    policyBasePremium +
193	      itemSurchargesFor(items) +
194	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
195	      PROCESSING_FEE,
196	  );
197	  return { premium };
198	};
199	
200	// A follow-up contract is any quote after the customer's first. Every step is a
201	// quote so far, so a step's position stands in for the number of quotes before
202	// it. That equivalence is this function and nothing else — once claim steps
203	// exist, a claim at index 0 would wrongly make a quote at index 1 a follow-up,
204	// and the fix is to count preceding QUOTE steps here.
205	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
206	
207	const insuranceSumFor = (items: Item[]): number =>
208	  sum(items.map((item) => INSURANCE_VALUES[item.type]));
209	
210	// MHPCO pays, so payouts round down.
211	const roundPayoutInMHPCOsFavour = Math.floor;
212	
213	// Each damage entry carries its own deductible: one dragon attack damaging two
214	// items is two damages, and MHPCO withholds 100 G from each.
215	const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;
216	
217	const claimFor = (claim: ClaimStep, steps: Step[]): ClaimResult => {
218	  const policyStep = steps[claim.policy] as QuoteStep;
219	  const cap = insuranceSumFor(policyStep.items) * CAP_MULTIPLE;
220	  const payout = roundPayoutInMHPCOsFavour(sum(claim.incident.damages.map(payoutForDamage)));
221	  return { payout, remainingCap: cap - payout };
222	};
223	
224	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
225	  const results = scenario.steps.map((step, stepIndex) =>
226	    step.op === "quote"
227	      ? quoteFor(step.items, scenario.customer, isFollowUpContract(stepIndex))
228	      : claimFor(step, scenario.steps),
229	  );
230	  return { results };
231	};
