const capFor = (policy: QuoteStep): number =>
  insuranceSumFor(policy.items) * CAP_MULTIPLE;

const claimFor = (claim: ClaimStep, policy: QuoteStep): ClaimResult => {
  const payout = roundPayoutInMHPCOsFavour(sum(claim.incident.damages.map(payoutForDamage)));
  return { payout, remainingCap: capFor(policy) - payout };
