// error-case tests will turn the throw into a reported error.
const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep => {
  const step = steps[claim.policy];
  if (step === undefined || !isQuote(step)) {
    throw new Error(`Claim references step ${claim.policy}, which is not a quote`);
